INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (7497,'zhTW','屠龍者兼技藝精湛的製皮匠？你總是讓我驚訝不已，英雄。我深感榮幸。$B$B請收下我即將傳授給你的東西。如果你要消滅黑龍軍團的殘部，這項知識將會證明是無比珍貴的。$B$B用母巢守護者的鱗片製作這件斗篷。它將能保護你與你的盟友，抵禦黑石之王……奈法利安的熾熱吐息。',0);
