INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (14351,'zhTW','所以你就是那個在希爾斯布萊德丘陵中擊潰聯盟部隊的$c？我早已聽聞你的名號。消息傳得可真快。$B$B如果你能繼續保持下去，部落用得上像你這樣的人才，$N。$B$B我們必須留意周遭的一切威脅，但只要那位國王還在領導他們，人類就會繼續是個麻煩。你已經證實了部落擁有足夠的實力，能及時終結這個威脅。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 14352 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (14352,'zhTW','我在北裂境的時候見過這種徽記。你說這是從掌管剃刀高地那些豬人的老巫婆身上找到的？$b$b如果我讓天災在這裡站穩腳跟，我就不得安寧。寫下這個的人——這個馬爾辛——顯然是巫妖王的僕人之一，這讓他成了一個目標。你的目標。$b$b他們休想奪取卡利姆多。$b$b',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 14353 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (14353,'zhTW','幹得好，$c!$b$b你阻止了天災在我們的土地上紮根，為部落爭了光。這樣的功績值得獎賞，而被遺忘者手邊的東西足夠讓他們勻出一些來。$b$b我們或許不清楚他們在那片沼澤裡做過的一切，但我們會查出來的。他們不可能永遠躲在黑暗中。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 14438 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (14438,'zhTW','$N，你認真看待這項任務，很好。尊重大地與其生靈是很重要的。生與死是一個循環……是必然的。沒有一方能脫離另一方而存在。花點時間仔細思考這一點，並且永遠不要忘記。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 14483 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (14483,'zhTW','你那裡拿的是什麼?$B$B哦嘿，這可不得了。真的不得了。這麼多瘋狂的細節全濃縮在這一個小包裹裡。謝謝——你真的幫了我們大忙，把這一切都給釐清了。跟你合作真愉快。',0);
