INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (24798,'zhTW','這樣一件強大的武器竟能從邪惡的魔爪中被拯救出來，在這樣的時局裡實在是個吉兆，$N。有奎爾德拉和忠貞的逐日者盟友在我們身邊，巫妖王有充分的理由感到恐懼。$B$B十字軍為我們最強大的盟友保有一批非凡的武器庫。既然你託付我們保管奎爾德拉，就讓我提供你從中挑選一件作為回報吧。',0);
