INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (24831,'zhTW','你是我們信念真正的鬥士，$N。沒有人能聲稱比你更全心投入這場戰鬥。$B$B你是智慧的堡壘，我們的盟友以最崇高的敬意談論你。他們之中許多人的性命都是你救回來的。$B$B請收下這份微薄的禮物，作為你無數勝利的獎賞。',0);
