INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (24833,'zhTW','你是我們信念真正的鬥士，$N。沒有人能聲稱比你更全心投入這場戰鬥。$B$B據說天災的爪牙對你的恐懼甚至超過了巫妖王本人。你就是復仇的化身。$B$B請收下這份微薄的禮物，作為你無數勝利的獎賞。',0);
