INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (24835,'zhTW','你是我們信念真正的鬥士，$N。沒有人能聲稱比你更全心投入這場戰鬥。$B$B你是我們盟友的靈感泉源，你堅定不移的勇氣甚至讓敵人最老練的將領也為之卻步。$B$B請收下這份微薄的禮物，作為你無數勝利的獎賞。',0);
