INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (24914,'zhTW','<在箱子的每一面刻劃出複雜的符文圖案後，一道蓋子的輪廓浮現出來，一聲喀嗒聲響徹整個密室。>$B$B給你，$R。',0);
