INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (25055,'zhTW','做得好，$N。但每制伏一個元素生物，就會有另一個取而代之。我們現在的辦法只是權宜之計。希望大地之環的同胞們能有更多進展。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 25180 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (25180,'zhTW','暮光之錘為什麼會對這些石板感興趣？布萊恩自己都寫道他幾乎不清楚它們的意義，不過他確實提到了與大地合而為一的事。我得儘快與探險者協會的同僚們商議，才能解讀這些石板。$B$B謝謝你，$N。沒有你的幫助，這些石板恐怕早已落入敵人之手。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 25181 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (25181,'zhTW','暮光之錘為什麼會對這些石板感興趣？就連我們最博學的學者也對它們的內容一頭霧水，要解讀恐怕得花上一些時間。如果暮光之錘知道這些遺物並且渴望得到它們，他們究竟還在圖謀些什麼？$B$B你能保護它們不被奪走，真是我們的幸運，$N。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 25228 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (25228,'zhTW','<托雷克翻閱著你收集來的卷軸。>$B$B不管這些人是誰，他們確實想要拉攏更多的追隨者。看來他們已經相當成功了。絕不能讓他們煽動奧格瑪的市民陷入恐慌與歇斯底里。我們必須遏止大眾對這個組織的興趣，並儘可能查明更多消息。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 25229 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (25229,'zhTW','這就是你能找到最優秀的一批飛行員候選人了？$B$B好吧，我看看能做些什麼。我向來擅長把最歪七扭八的一堆零件變成一台運轉順暢的戰鬥機器，這次我也不會例外。$B$B好了，該開工了!',0);
